local companionData = {
  slugs = {
    [SLUG] = {
      name = ROOT_ID,
      author = "WoloUI / Halcones de Chicureo",
      encoded = ENCODED,
      wagoVersion = "1",
      wagoSemver = "1.0.0",
      source = "Wago",
      versionNote = "Bundled by RetreatUI for Zul'Gurub encounter coverage.",
    },
  },
  stash = {},
  stopmotionFiles = {},
}

local registered = false

local function RegisterCompanionData()
  if registered then return true end
  if type(WeakAuras) ~= "table" or type(WeakAuras.AddCompanionData) ~= "function" then return false end
  local ok = pcall(WeakAuras.AddCompanionData, companionData)
  if not ok then return false end
  registered = true
  RUI._zgRaidPackCompanionRegistered = true
  return true
end

function RUI:IsZGRaidPackInstalled()
  if type(WeakAuras) ~= "table" or type(WeakAuras.GetData) ~= "function" then return false end
  local ok, data = pcall(WeakAuras.GetData, ROOT_ID)
  return ok and type(data) == "table"
end

function RUI:OpenZGRaidPackImport()
  if type(WeakAuras) ~= "table" then
    self:Print("WeakAuras is not installed or loaded.")
    return false
  end
  RegisterCompanionData()
  if self:IsZGRaidPackInstalled() then
    self:Print("The Zul'Gurub raid pack is already installed in WeakAuras.")
    return true
  end
  if type(WeakAuras.Import) ~= "function" then
    self:Print("This WeakAuras version does not expose the import API.")
    return false
  end
  local ok, accepted, reason = pcall(WeakAuras.Import, ENCODED)
  if not ok or accepted ~= true then
    self:Print("Could not open the Zul'Gurub raid-pack import" .. (reason and (": " .. tostring(reason)) or "."))
    return false
  end
  return true
end

SLASH_RETREATUIZG1 = "/ruizg"
SlashCmdList.RETREATUIZG = function()
  RUI:OpenZGRaidPackImport()
end

local events = CreateFrame("Frame")
events:RegisterEvent("ADDON_LOADED")
events:RegisterEvent("PLAYER_LOGIN")
events:SetScript("OnEvent", function(_, event, addonName)
  if event == "ADDON_LOADED" and addonName ~= "WeakAuras" and addonName ~= "RetreatUI" then return end
  RegisterCompanionData()
end)

RegisterCompanionData()
